'use strict';
(()=>{const A=RepoAccount,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let busy=false,timer,items=[],cursor=null,hadUser=false;
function render(items){const labels={queued:'Queued for scan',processing:'Scanning repository',imported:'Imported into saved catalogue',retry:'Waiting for an automatic retry',unavailable:'Repository unavailable'};$('#submission-list').innerHTML=items.length?items.map(r=>`<article class="promotion-record"><span class="promotion-status">${esc(labels[r.status]||r.status)}</span><h3>${esc(r.canonical_name||r.repo_name)}</h3>${r.status==='imported'?(r.with_demo?`<p>A demo link was found. New listings appear after the next daily catalogue publication at 06:35 UTC, or when an administrator publishes sooner.</p><a class="button outline" href="/?project=${encodeURIComponent(r.canonical_name||r.repo_name)}">View listing</a>`:'<p>This earlier submission has no demo link and is no longer eligible for the library. Add a demo link to its README or homepage before submitting again.</p>'):r.status==='retry'?'<p>A temporary error interrupted this scan. Your submission is saved and will be checked again.</p>':r.status==='unavailable'?'<p>This repository could not be added. It must be public and include a demo link in its README or homepage. Add a demo link or check the repository URL, then submit again.</p>':''}<p class="submission-time">Submitted ${esc(new Date(r.created_at).toLocaleString())}${r.checked_at?' · Checked '+esc(new Date(r.checked_at).toLocaleString()):''} · ${Number(r.attempts)||0} scan attempts</p></article>`).join(''):'<p class="loading-note">Your submitted repositories will appear here.</p>'}
async function load(){const data=await A.request('/api/submissions');items=data.items;cursor=data.nextCursor;render(items);$('#more-submissions').hidden=cursor===null||cursor===undefined;$('#submission-request button').disabled=!data.workerConfigured;if(!data.workerConfigured)$('#submission-message').textContent='Repository submission is awaiting setup. Existing requests remain saved.';return data}
async function task(fn){if(busy)return;busy=true;$('#refresh-submissions').disabled=true;$('#submission-request button').disabled=true;try{await fn()}catch(e){$('#submission-message').textContent=e.message}finally{busy=false;$('#refresh-submissions').disabled=false;try{await load()}catch{}}}
$('#submission-request').onsubmit=e=>{e.preventDefault();void task(async()=>{const result=await A.request('/api/submissions',{method:'POST',body:JSON.stringify({repository:$('#submission-repo').value})});$('#submission-repo').value='';$('#submission-message').textContent=!result.queued?'This repository is already in your submissions. Its current status is shown below.':result.scanRequested?'Submission saved and a scan has been requested.':'Submission saved. We’ll scan it in the next submission batch.'})};$('#refresh-submissions').onclick=()=>void task(load);$('#more-submissions').onclick=async()=>{if(busy||cursor==null)return;busy=true;$('#more-submissions').disabled=true;try{const data=await A.request('/api/submissions?cursor='+cursor);items.push(...data.items);cursor=data.nextCursor;render(items);$('#more-submissions').hidden=cursor==null}catch(e){$('#submission-message').textContent=e.message}finally{busy=false;$('#more-submissions').disabled=false}};
(async()=>{while(!A.ready)await new Promise(r=>setTimeout(r,50));if(!A.user?.githubConnected){$('#submission-gate').innerHTML=A.user?'<p>Connect your GitHub account to submit a repository and track its progress. Your likes and collection stay with this account.</p><a class="button lime" href="/api/auth?action=link-github&return=%2Fsubmissions.html">Connect GitHub ↗</a>':'<p>Sign in with GitHub to submit a repository and track its progress.</p><a class="button lime" href="/api/auth?action=start&return=%2Fsubmissions.html">Sign in with GitHub ↗</a><p class="small">By signing in you agree to our <a href="/terms.html">Terms of Service</a> and acknowledge our <a href="/privacy.html">Privacy Policy</a>.</p>';return}hadUser=true;$('#submission-gate').hidden=true;$('#submission-workspace').hidden=false;try{await load();timer=setInterval(()=>{if(!document.hidden&&!busy&&items.length<=50)void load().catch(()=>{})},30000)}catch(e){$('#submission-request button').disabled=true;$('#submission-message').textContent=e.message}})();window.addEventListener('pagehide',()=>clearInterval(timer));window.addEventListener('reposhelf-account',()=>{if(hadUser&&A.ready&&!A.user){clearInterval(timer);location.href='/submissions.html'}});
})();
